   432  int mz_inflate(mz_streamp pStream, int flush)
   433  {
   434      inflate_state *pState;
   435      mz_uint n, first_call, decomp_flags = TINFL_FLAG_COMPUTE_ADLER32;
   436      size_t in_bytes, out_bytes, orig_avail_in;
   437      tinfl_status status;
   438
   439      if ((!pStream) || (!pStream->state))
   440          return MZ_STREAM_ERROR;
   441      if (flush == MZ_PARTIAL_FLUSH)
   442          flush = MZ_SYNC_FLUSH;
   443      if ((flush) && (flush != MZ_SYNC_FLUSH) && (flush != MZ_FINISH))
   444          return MZ_STREAM_ERROR;
   445
   446      pState = (inflate_state *)pStream->state;
   447      if (pState->m_window_bits > 0)
   448          decomp_flags |= TINFL_FLAG_PARSE_ZLIB_HEADER;
   449      orig_avail_in = pStream->avail_in;
   450
   451      first_call = pState->m_first_call;
   452      pState->m_first_call = 0;
   453      if (pState->m_last_status < 0)
   454          return MZ_DATA_ERROR;
   455
   456      if (pState->m_has_flushed && (flush != MZ_FINISH))
   457          return MZ_STREAM_ERROR;
   458      pState->m_has_flushed |= (flush == MZ_FINISH);
   459
   460      if ((flush == MZ_FINISH) && (first_call))
   461      {
   462          /* MZ_FINISH on the first call implies that the input and output buffers are large enough to hold the entire compressed/decompressed file. */
   463          decomp_flags |= TINFL_FLAG_USING_NON_WRAPPING_OUTPUT_BUF;
   464          in_bytes = pStream->avail_in;
   465          out_bytes = pStream->avail_out;
   466          status = tinfl_decompress(&pState->m_decomp, pStream->next_in, &in_bytes, pStream->next_out, pStream->next_out, &out_bytes, decomp_flags);
   467          pState->m_last_status = status;
   468          pStream->next_in += (mz_uint)in_bytes;
   469          pStream->avail_in -= (mz_uint)in_bytes;
   470          pStream->total_in += (mz_uint)in_bytes;
   471          pStream->adler = tinfl_get_adler32(&pState->m_decomp);
   472          pStream->next_out += (mz_uint)out_bytes;
   473          pStream->avail_out -= (mz_uint)out_bytes;
   474          pStream->total_out += (mz_uint)out_bytes;
   475
   476          if (status < 0)
   477              return MZ_DATA_ERROR;
   478          else if (status != TINFL_STATUS_DONE)
   479          {
   480              pState->m_last_status = TINFL_STATUS_FAILED;
   481              return MZ_BUF_ERROR;
   482          }
   483          return MZ_STREAM_END;
   484      }
   485      /* flush != MZ_FINISH then we must assume there's more input. */
   486      if (flush != MZ_FINISH)
   487          decomp_flags |= TINFL_FLAG_HAS_MORE_INPUT;
   488
   489      if (pState->m_dict_avail)
   490      {
   491          n = MZ_MIN(pState->m_dict_avail, pStream->avail_out);
   492          memcpy(pStream->next_out, pState->m_dict + pState->m_dict_ofs, n);
   493          pStream->next_out += n;
   494          pStream->avail_out -= n;
   495          pStream->total_out += n;
   496          pState->m_dict_avail -= n;
   497          pState->m_dict_ofs = (pState->m_dict_ofs + n) & (TINFL_LZ_DICT_SIZE - 1);
   498          return ((pState->m_last_status == TINFL_STATUS_DONE) && (!pState->m_dict_avail)) ? MZ_STREAM_END : MZ_OK;
   499      }
   500
   501      for (;;)
   502      {
   503          in_bytes = pStream->avail_in;
   504          out_bytes = TINFL_LZ_DICT_SIZE - pState->m_dict_ofs;
   505
   506          status = tinfl_decompress(&pState->m_decomp, pStream->next_in, &in_bytes, pState->m_dict, pState->m_dict + pState->m_dict_ofs, &out_bytes, decomp_flags);
   507          pState->m_last_status = status;
   508
   509          pStream->next_in += (mz_uint)in_bytes;
   510          pStream->avail_in -= (mz_uint)in_bytes;
   511          pStream->total_in += (mz_uint)in_bytes;
   512          pStream->adler = tinfl_get_adler32(&pState->m_decomp);
   513
   514          pState->m_dict_avail = (mz_uint)out_bytes;
   515
   516          n = MZ_MIN(pState->m_dict_avail, pStream->avail_out);
   517          memcpy(pStream->next_out, pState->m_dict + pState->m_dict_ofs, n);
   518          pStream->next_out += n;
   519          pStream->avail_out -= n;
   520          pStream->total_out += n;
   521          pState->m_dict_avail -= n;
   522          pState->m_dict_ofs = (pState->m_dict_ofs + n) & (TINFL_LZ_DICT_SIZE - 1);
   523
   524          if (status < 0)
   525              return MZ_DATA_ERROR; /* Stream is corrupted (there could be some uncompressed data left in the output dictionary - oh well). */
   526          else if ((status == TINFL_STATUS_NEEDS_MORE_INPUT) && (!orig_avail_in))
   527              return MZ_BUF_ERROR; /* Signal caller that we can't make forward progress without supplying more input or by setting flush to MZ_FINISH. */
   528          else if (flush == MZ_FINISH)
   529          {
   530              /* The output buffer MUST be large to hold the remaining uncompressed data when flush==MZ_FINISH. */
   531              if (status == TINFL_STATUS_DONE)
   532                  return pState->m_dict_avail ? MZ_BUF_ERROR : MZ_STREAM_END;
   533              /* status here must be TINFL_STATUS_HAS_MORE_OUTPUT, which means there's at least 1 more byte on the way. If there's no more room left in the output buffer then something is wrong. */
   534              else if (!pStream->avail_out)
   535                  return MZ_BUF_ERROR;
   536          }
   537          else if ((status == TINFL_STATUS_DONE) || (!pStream->avail_in) || (!pStream->avail_out) || (pState->m_dict_avail))
   538              break;
   539      }
   540
   541      return ((status == TINFL_STATUS_DONE) && (!pState->m_dict_avail)) ? MZ_STREAM_END : MZ_OK;
   542  }
