   544  int mz_inflateEnd(mz_streamp pStream)
   545  {
   546      if (!pStream)
   547          return MZ_STREAM_ERROR;
   548      if (pStream->state)
   549      {
   550          pStream->zfree(pStream->opaque, pStream->state);
   551          pStream->state = NULL;
   552      }
   553      return MZ_OK;
   554  }
   555  int mz_uncompress2(unsigned char *pDest, mz_ulong *pDest_len, const unsigned char *pSource, mz_ulong *pSource_len)
   556  {
   557      mz_stream stream;
   558      int status;
   559      memset(&stream, 0, sizeof(stream));
   560
   561      /* In case mz_ulong is 64-bits (argh I hate longs). */
   562      if ((*pSource_len | *pDest_len) > 0xFFFFFFFFU)
   563          return MZ_PARAM_ERROR;
   564
   565      stream.next_in = pSource;
   566      stream.avail_in = (mz_uint32)*pSource_len;
   567      stream.next_out = pDest;
   568      stream.avail_out = (mz_uint32)*pDest_len;
   569
   570      status = mz_inflateInit(&stream);
   571      if (status != MZ_OK)
   572          return status;
   573
   574      status = mz_inflate(&stream, MZ_FINISH);
   575      *pSource_len = *pSource_len - stream.avail_in;
   576      if (status != MZ_STREAM_END)
   577      {
   578          mz_inflateEnd(&stream);
   579          return ((status == MZ_BUF_ERROR) && (!stream.avail_in)) ? MZ_DATA_ERROR : status;
   580      }
   581      *pDest_len = stream.total_out;
   582
   583      return mz_inflateEnd(&stream);
   584  }
