    55  /* Return status. */
    56  typedef enum {
    57      /* This flags indicates the inflator needs 1 or more input bytes to make forward progress, but the caller is indicating that no more are available. The compressed data */
    58      /* is probably corrupted. If you call the inflator again with more bytes it'll try to continue processing the input but this is a BAD sign (either the data is corrupted or you called it incorrectly). */
    59      /* If you call it again with no input you'll just get TINFL_STATUS_FAILED_CANNOT_MAKE_PROGRESS again. */
    60      TINFL_STATUS_FAILED_CANNOT_MAKE_PROGRESS = -4,
    61
    62      /* This flag indicates that one or more of the input parameters was obviously bogus. (You can try calling it again, but if you get this error the calling code is wrong.) */
    63      TINFL_STATUS_BAD_PARAM = -3,
    64
    65      /* This flags indicate the inflator is finished but the adler32 check of the uncompressed data didn't match. If you call it again it'll return TINFL_STATUS_DONE. */
    66      TINFL_STATUS_ADLER32_MISMATCH = -2,
    67
    68      /* This flags indicate the inflator has somehow failed (bad code, corrupted input, etc.). If you call it again without resetting via tinfl_init() it it'll just keep on returning the same status failure code. */
    69      TINFL_STATUS_FAILED = -1,
    70
    71      /* Any status code less than TINFL_STATUS_DONE must indicate a failure. */
    72
    73      /* This flag indicates the inflator has returned every byte of uncompressed data that it can, has consumed every byte that it needed, has successfully reached the end of the deflate stream, and */
    74      /* if zlib headers and adler32 checking enabled that it has successfully checked the uncompressed data's adler32. If you call it again you'll just get TINFL_STATUS_DONE over and over again. */
    75      TINFL_STATUS_DONE = 0,
    76
    77      /* This flag indicates the inflator MUST have more input data (even 1 byte) before it can make any more forward progress, or you need to clear the TINFL_FLAG_HAS_MORE_INPUT */
    78      /* flag on the next call if you don't have any more source data. If the source data was somehow corrupted it's also possible (but unlikely) for the inflator to keep on demanding input to */
    79      /* proceed, so be sure to properly set the TINFL_FLAG_HAS_MORE_INPUT flag. */
    80      TINFL_STATUS_NEEDS_MORE_INPUT = 1,
    81
    82      /* This flag indicates the inflator definitely has 1 or more bytes of uncompressed data available, but it cannot write this data into the output buffer. */
    83      /* Note if the source compressed data was corrupted it's possible for the inflator to return a lot of uncompressed data to the caller. I've been assuming you know how much uncompressed data to expect */
    84      /* (either exact or worst case) and will stop calling the inflator and fail after receiving too much. In pure streaming scenarios where you have no idea how many bytes to expect this may not be possible */
    85      /* so I may need to add some code to address this. */
    86      TINFL_STATUS_HAS_MORE_OUTPUT = 2
    87  } tinfl_status;
